{"path": "stage1.py", "content": "import csv


def parse_orders(path):
    """Read a CSV with header id,qty,price and return a list of dicts."""
    rows = []
    with open(path, newline="") as f:
        reader = csv.DictReader(f)
        for row in reader:
            rows.append({
                "id": int(row["id"]),
                "qty": int(row["qty"]),
                "price": int(row["price"]),
            })
    return rows
"}

{"path": "stage3.py", "content": "def total_by_price(rows):
    """Sum qty grouped by price. Returns {price: total_qty}."""
    totals = {}
    for row in rows:
        totals[row["price"]] = totals.get(row["price"], 0) + row["qty"]
    return totals
"}

{"path": "stage4.py", "content": "def report(totals):
    """Render {price: qty} as ascending-price lines "<price>:<qty>", newline-terminated."""
    return "".join(f"{price}:{totals[price]}\n" for price in sorted(totals))
"}
